-- Plaquinhas do buffet: catálogo bilíngue e listas salvas.

CREATE TABLE "BuffetPlateItem" (
    "id" TEXT NOT NULL,
    "namePt" TEXT NOT NULL,
    "nameEn" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "BuffetPlateItem_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "BuffetPlateList" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "kind" TEXT NOT NULL DEFAULT 'BUFFET',
    "eventDate" DATE,
    "format" TEXT NOT NULL DEFAULT 'std',
    "theme" TEXT NOT NULL DEFAULT 'wine',
    "items" JSONB NOT NULL DEFAULT '[]',
    "createdById" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "BuffetPlateList_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "BuffetPlateItem_namePt_key" ON "BuffetPlateItem"("namePt");
CREATE INDEX "BuffetPlateItem_isActive_category_idx" ON "BuffetPlateItem"("isActive", "category");
CREATE INDEX "BuffetPlateList_updatedAt_idx" ON "BuffetPlateList"("updatedAt");

-- Catálogo inicial: 761 pratos padronizados da planilha do buffet + 65 itens de coffee break,
-- com a tradução em inglês. Ids fixos para as listas abaixo poderem referenciar os itens.
ON CONFLICT ("namePt") DO NOTHING;

-- Listas que a operação já usava (abas da planilha) e um coffee break de exemplo.
ON CONFLICT ("id") DO NOTHING;
